// Calculate Days & Risk (v2.0)
// Risk = days in current stage vs SLA, combined with days since last activity.
// Also extracts per-stage history (cumulative time + exit date) for velocity stats.
const cfg = $('Pipeline Settings').first().json;

const stageNameMap = {
  [cfg.closedWonStageId]: 'Closed Won',
  [cfg.closedLostStageId]: 'Closed Lost'
};
const slaThresholds = {};
cfg.stages.forEach(s => {
  stageNameMap[s.id] = s.name;
  slaThresholds[s.name] = Number(s.slaDays);
});

const lossProbability = {
  HIGH: Number(cfg.lossProbabilityHigh),
  MEDIUM: Number(cfg.lossProbabilityMedium),
  OK: 0
};
const mediumShare = Number(cfg.mediumThresholdShare);
const activityThreshold = Number(cfg.activityThresholdDays ?? 7);

// Owner ID -> name (falls back to the ID if the owners request failed)
const ownerMap = {};
const ownersResponse = $('Get HubSpot Owners').first().json || {};
(ownersResponse.results || []).forEach(o => {
  const name = [o.firstName, o.lastName].filter(Boolean).join(' ').trim();
  ownerMap[String(o.id)] = name || o.email || String(o.id);
});

const MS_PER_DAY = 1000 * 60 * 60 * 24;
const today = new Date();

// Accepts epoch milliseconds (number or numeric string) or an ISO date string
const parseHubSpotDate = value => {
  if (value === null || value === undefined || value === '') return null;
  const str = String(value).trim();
  const date = /^[0-9]+$/.test(str) ? new Date(Number(str)) : new Date(str);
  return isNaN(date.getTime()) ? null : date;
};
const parseNumber = value => {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};
const daysSince = date => (date ? Math.floor((today - date) / MS_PER_DAY) : null);

return $input.all().map(deal => {
  const props = deal.json.properties || {};
  const val = key => props[key]?.value;

  const deal_id = deal.json.dealId;
  const deal_name = val('dealname') || 'N/A';
  const stage_id = val('dealstage') || 'Unknown';
  const stage = stageNameMap[stage_id] || 'Unknown Stage';
  const amount = parseFloat(val('amount') || 0) || 0;
  const stage_entry_date = val('hs_v2_date_entered_current_stage') || null;
  const owner_id = val('hubspot_owner_id') || null;
  const owner_name = owner_id ? (ownerMap[String(owner_id)] || `Owner ${owner_id}`) : 'Unassigned';

  // Days in current stage
  const stage_date = parseHubSpotDate(stage_entry_date);
  const days_in_stage = stage_date ? daysSince(stage_date) : 0;
  const sla_threshold = slaThresholds[stage] ?? null;

  // Days since last activity (notes_last_updated = HubSpot "Last activity date")
  const last_activity_date = parseHubSpotDate(val('notes_last_updated'));
  const days_since_activity = daysSince(last_activity_date);
  const is_inactive = days_since_activity === null || days_since_activity > activityThreshold;
  const activityText = days_since_activity === null
    ? 'no activity logged'
    : (is_inactive ? `no activity for ${days_since_activity} days` : `active ${days_since_activity} days ago`);

  // Data quality flags
  const isClosed = stage === 'Closed Won' || stage === 'Closed Lost';
  let data_issue = null;
  if (!isClosed && stage === 'Unknown Stage') data_issue = 'stage_not_in_pipeline_settings';
  else if (!isClosed && !stage_date) data_issue = 'missing_stage_entry_date';

  // Risk matrix: stage age x activity
  //   past SLA + inactive            -> HIGH
  //   past SLA + recent activity     -> MEDIUM
  //   past 70% of SLA + inactive     -> MEDIUM
  //   everything else                -> OK
  let risk_level, age_status = null, risk_reason = null;
  if (isClosed) risk_level = 'CLOSED';
  else if (sla_threshold === null || !stage_date) risk_level = 'UNKNOWN';
  else {
    if (days_in_stage > sla_threshold) age_status = 'past_sla';
    else if (days_in_stage > sla_threshold * mediumShare) age_status = 'approaching_sla';
    else age_status = 'on_track';

    if (age_status === 'past_sla' && is_inactive) risk_level = 'HIGH';
    else if (age_status === 'past_sla') risk_level = 'MEDIUM';
    else if (age_status === 'approaching_sla' && is_inactive) risk_level = 'MEDIUM';
    else risk_level = 'OK';

    const ageText = age_status === 'past_sla'
      ? `past SLA (+${days_in_stage - sla_threshold} days)`
      : age_status === 'approaching_sla' ? 'close to SLA' : 'within SLA';
    risk_reason = `${ageText}, ${activityText}`;
  }

  const revenue_at_risk = amount * (lossProbability[risk_level] || 0);

  // Per-stage history for velocity: cumulative time (ms) and exit date per configured stage.
  // HubSpot only fills these once a deal has LEFT the stage.
  const stage_history = {};
  cfg.stages.forEach(s => {
    const key = s.propertyKey || s.id;
    const cumulativeMs = parseNumber(val(`hs_v2_cumulative_time_in_${key}`));
    const exitedAt = parseHubSpotDate(val(`hs_v2_date_exited_${key}`));
    if (cumulativeMs !== null && exitedAt) {
      stage_history[s.name] = {
        days: Math.round((cumulativeMs / MS_PER_DAY) * 10) / 10,
        exitedAt: exitedAt.toISOString()
      };
    }
  });

  return {
    json: {
      deal_id,
      deal_name,
      stage,
      stage_id,
      amount,
      stage_entry_date,
      owner_id,
      owner_name,
      days_in_stage,
      sla_threshold,
      days_since_activity,
      is_inactive,
      age_status,
      risk_level,
      risk_reason,
      revenue_at_risk,
      data_issue,
      stage_history,
      stage_date: stage_date ? stage_date.toISOString().split('T')[0] : null
    }
  };
});

// Create Risk Summary (v2.0): risk counts, tiered revenue at risk, prioritized top-3 deals
const deals = $input.all().map(d => d.json);
const CURRENCY = $('Pipeline Settings').first().json.currency || '';
const fmt = n => CURRENCY + Math.round(n || 0).toLocaleString('en-US');
const sumRisk = list => list.reduce((sum, d) => sum + d.revenue_at_risk, 0);

const highRiskDeals = deals.filter(d => d.risk_level === 'HIGH');
const mediumRiskDeals = deals.filter(d => d.risk_level === 'MEDIUM');
const openDeals = deals.filter(d => d.risk_level !== 'CLOSED' && d.risk_level !== 'UNKNOWN');

const highRiskCount = highRiskDeals.length;
const mediumRiskCount = mediumRiskDeals.length;
const totalAtRisk = highRiskCount + mediumRiskCount;
const inactiveOpenCount = openDeals.filter(d => d.is_inactive).length;

const highRiskRevenue = Math.round(sumRisk(highRiskDeals));
const mediumRiskRevenue = Math.round(sumRisk(mediumRiskDeals));
const totalRevenueAtRisk = highRiskRevenue + mediumRiskRevenue;

// Priority: HIGH before MEDIUM, then revenue at risk, then days in stage
const tierRank = { HIGH: 2, MEDIUM: 1 };
const topRiskDeals = [...highRiskDeals, ...mediumRiskDeals]
  .sort((a, b) =>
    (tierRank[b.risk_level] - tierRank[a.risk_level]) ||
    (b.revenue_at_risk - a.revenue_at_risk) ||
    (b.days_in_stage - a.days_in_stage)
  )
  .slice(0, 3);

const rankEmoji = ['1️⃣', '2️⃣', '3️⃣'];
const topDealsText = topRiskDeals.length
  ? topRiskDeals.map((d, i) =>
      `${rankEmoji[i]} *${d.deal_name}* [${d.risk_level}]\n` +
      `• ${d.stage}: ${d.days_in_stage} days (SLA ${d.sla_threshold}) | ${d.risk_reason}\n` +
      `• Amount: ${fmt(d.amount)} | Owner: ${d.owner_name}`
    ).join('\n')
  : '✅ No deals at risk this week';

return {
  json: {
    totalAtRisk,
    highRiskCount,
    mediumRiskCount,
    openDealCount: openDeals.length,
    inactiveOpenCount,
    highRiskRevenue,
    mediumRiskRevenue,
    totalRevenueAtRisk,
    highRiskRevenueFormatted: fmt(highRiskRevenue),
    mediumRiskRevenueFormatted: fmt(mediumRiskRevenue),
    totalRevenueAtRiskFormatted: fmt(totalRevenueAtRisk),
    topRiskDeals,
    topDealsText
  }
};

// Calculate Trend: week-over-week at-risk comparison (history from Google Sheets)
const summary = $('Create Risk Summary').first().json;
const currentAtRisk = summary.totalAtRisk || 0;
const todayStr = $today.toFormat('yyyy-MM-dd');

// Sheet rows: drop empty rows and today's row (so manual re-runs don't compare against themselves)
const history = $input.all()
  .map(item => item.json)
  .filter(r =>
    r['At-Risk Count'] !== undefined &&
    r['At-Risk Count'] !== '' &&
    String(r['Week Of']) !== todayStr
  );

const lastRow = history.length ? history[history.length - 1] : null;
const previousWeekAtRisk = lastRow ? Number(lastRow['At-Risk Count']) : null;

let trend = 0, trendPercent = 0, trendEmoji, trendLabel, trendString;

if (previousWeekAtRisk === null || Number.isNaN(previousWeekAtRisk)) {
  // First run: no history yet
  trendEmoji = '⚪';
  trendLabel = 'Baseline';
  trendString = '⚪ Baseline week (no history yet)';
} else {
  trend = currentAtRisk - previousWeekAtRisk;
  trendPercent = previousWeekAtRisk > 0
    ? Math.round((trend / previousWeekAtRisk) * 100)
    : 0;

  if (trend > 0)      { trendEmoji = '🔴'; trendLabel = 'Worse'; }
  else if (trend < 0) { trendEmoji = '🟢'; trendLabel = 'Better'; }
  else                { trendEmoji = '⚪'; trendLabel = 'Flat'; }

  trendString = trend !== 0
    ? `${trendEmoji} ${trend > 0 ? '+' : ''}${trend} deals (was ${previousWeekAtRisk})`
    : `${trendEmoji} Flat (was ${previousWeekAtRisk} deals)`;
}

return {
  json: {
    ...summary,
    currentAtRisk,
    previousWeekAtRisk,
    trend,
    trendPercent,
    trendEmoji,
    trendLabel,
    trendString
  }
};

// Calculate Stage Stats (v2.0)
// Two lenses per stage:
//  1. Velocity (historical): median days deals spent in the stage, for deals that EXITED it
//     within the lookback window. This drives bottlenecks and slowest/fastest stage.
//  2. Aging (current): average days the OPEN deals have been sitting in the stage.
const deals = $input.all().map(d => d.json);
const cfg = $('Pipeline Settings').first().json;
const CURRENCY = cfg.currency || '';
const fmt = n => CURRENCY + Math.round(n || 0).toLocaleString('en-US');
const lookbackDays = Number(cfg.velocityLookbackDays ?? 90);
const minSample = Number(cfg.velocityMinSample ?? 3);
const cutoff = new Date(Date.now() - lookbackDays * 24 * 60 * 60 * 1000);

const median = arr => {
  if (!arr.length) return null;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
};
const round1 = n => (n === null ? null : Math.round(n * 10) / 10);
const sumRisk = list => list.reduce((sum, d) => sum + d.revenue_at_risk, 0);

const stages = cfg.stages.map(s => s.name);
const sla = {};
cfg.stages.forEach(s => { sla[s.name] = Number(s.slaDays); });

const stageStats = {};
stages.forEach(stage => {
  // Current (open deals in this stage)
  const openDeals = deals.filter(
    d => d.stage === stage && d.risk_level !== 'CLOSED' && d.risk_level !== 'UNKNOWN'
  );
  const highDeals = openDeals.filter(d => d.risk_level === 'HIGH');
  const mediumDeals = openDeals.filter(d => d.risk_level === 'MEDIUM');
  const openAvgDays = openDeals.length
    ? Math.round(openDeals.reduce((sum, d) => sum + d.days_in_stage, 0) / openDeals.length)
    : 0;

  // Historical (any deal, open or closed, that exited this stage in the lookback window)
  const durations = deals
    .map(d => d.stage_history && d.stage_history[stage])
    .filter(h => h && new Date(h.exitedAt) >= cutoff)
    .map(h => h.days);
  const velocitySample = durations.length;
  const velocityMedianDays = velocitySample >= minSample ? round1(median(durations)) : null;

  stageStats[stage] = {
    sla: sla[stage],
    velocityMedianDays,
    velocitySample,
    openAvgDays,
    dealCount: openDeals.length,
    highRisk: highDeals.length,
    mediumRisk: mediumDeals.length,
    atRiskCount: highDeals.length + mediumDeals.length,
    highRiskRevenue: Math.round(sumRisk(highDeals)),
    mediumRiskRevenue: Math.round(sumRisk(mediumDeals)),
    stageRevenueAtRisk: Math.round(sumRisk(openDeals)),
    // Aging: open deals already sit longer than SLA on average
    aging: openDeals.length > 0 && openAvgDays > sla[stage]
  };
});

// Slowest / fastest stage by historical velocity, relative to SLA (stages differ in length)
const measured = stages.filter(s => stageStats[s].velocityMedianDays !== null);
const ratio = s => stageStats[s].velocityMedianDays / stageStats[s].sla;
const byRatio = [...measured].sort((a, b) => ratio(b) - ratio(a));
const slowestStage = byRatio[0] || null;
const fastestStage = byRatio.length ? byRatio[byRatio.length - 1] : null;
const slowestAvgDays = slowestStage ? stageStats[slowestStage].velocityMedianDays : 0;
const fastestAvgDays = fastestStage ? stageStats[fastestStage].velocityMedianDays : 0;

// Bottlenecks: typical (median) time in stage above SLA
const bottlenecks = measured
  .filter(s => stageStats[s].velocityMedianDays > stageStats[s].sla)
  .map(s => ({
    stage: s,
    medianDays: stageStats[s].velocityMedianDays,
    sla: stageStats[s].sla,
    daysOverSla: round1(stageStats[s].velocityMedianDays - stageStats[s].sla),
    sample: stageStats[s].velocitySample,
    openDeals: stageStats[s].dealCount,
    atRiskCount: stageStats[s].atRiskCount
  }))
  .sort((a, b) => b.daysOverSla - a.daysOverSla);

const agingStages = stages.filter(s => stageStats[s].aging);

const bottleneckWarnings = bottlenecks
  .map(b => `• ${b.stage}: typically ${b.medianDays} days (SLA ${b.sla}, +${b.daysOverSla}) | based on ${b.sample} deals`)
  .join('\n');

// Slack text blocks
const stageBreakdownText = stages
  .map(stage => {
    const s = stageStats[stage];
    const velocity = s.velocityMedianDays !== null
      ? `typically ${s.velocityMedianDays}d (n=${s.velocitySample})`
      : `typical time n/a (n=${s.velocitySample})`;
    return `• ${stage}: ${s.atRiskCount} at risk of ${s.dealCount} open | ${velocity} vs SLA ${s.sla}d | open avg ${s.openAvgDays}d`;
  })
  .join('\n');

const pipelineHealthText = slowestStage
  ? `• Slowest vs SLA: ${slowestStage} (typically ${slowestAvgDays} days, SLA ${stageStats[slowestStage].sla})\n` +
    `• Fastest vs SLA: ${fastestStage} (typically ${fastestAvgDays} days, SLA ${stageStats[fastestStage].sla})\n` +
    `_Typical = median for deals that left the stage in the last ${lookbackDays} days_`
  : `• Not enough stage history yet (needs ${minSample}+ deals per stage in the last ${lookbackDays} days)`;

let bottleneckText = bottlenecks.length
  ? `⚠️ ${bottlenecks.length} bottleneck${bottlenecks.length > 1 ? 's' : ''} (typical time above SLA):\n${bottleneckWarnings}`
  : (measured.length ? '✅ No bottlenecks: typical stage times within SLA' : '');
if (agingStages.length) {
  bottleneckText += `${bottleneckText ? '\n' : ''}⏳ Aging now (open deals avg above SLA): ${agingStages.map(s => `${s} (${stageStats[s].openAvgDays}d)`).join(', ')}`;
}

return {
  json: {
    stageStats,
    slowestStage,
    slowestAvgDays,
    fastestStage,
    fastestAvgDays,
    bottleneckCount: bottlenecks.length,
    bottlenecks,
    agingStages,
    bottleneckWarnings,
    stageBreakdownText,
    pipelineHealthText,
    bottleneckText
  }
};

